export function faLabel(value: string, replacements: Record<string, string | number> = {}): string {
  let translated = faOverrides[value] ?? faLabels[value] ?? faContent[value] ?? value;

  for (const [key, replacement] of Object.entries(replacements)) {
    translated = translated.replaceAll(`{{${key}}}`, String(replacement));
  }

  return translated;
}

